11	
12	namespace ErrorCodes
13	{
14	    extern const int ILLEGAL_TYPE_OF_ARGUMENT;
15	    extern const int TOO_LARGE_ARRAY_SIZE;
16	}
17	
18	/// Reasonable threshold.
19	static constexpr size_t max_arrays_size_in_columns = 1000000000;
20	
21	
22	/* arrayWithConstant(num, const) - make array of constants with length num.
23	 * arrayWithConstant(3, 'hello') = ['hello', 'hello', 'hello']
24	 * arrayWithConstant(1, 'hello') = ['hello']
25	 * arrayWithConstant(0, 'hello') = []
26	 */
27	
28	class FunctionArrayWithConstant : public IFunction
29	{
30	public:
31	    static constexpr auto name = "arrayWithConstant";
32	
33	    static FunctionPtr create(ContextPtr) { return std::make_shared<FunctionArrayWithConstant>(); }
34	
35	    String getName() const override { return name; }
36	    size_t getNumberOfArguments() const override { return 2; }
37	
38	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
39	
40	    DataTypePtr getReturnTypeImpl(const DataTypes & arguments) const override
41	    {
42	        if (!isNativeNumber(arguments[0]))
43	            throw Exception("Illegal type " + arguments[0]->getName() +
44	                " of argument of function " + getName() +
45	                ", expected Integer", ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
46	        return std::make_shared<DataTypeArray>(arguments[1]);
47	    }
48	
49	    bool useDefaultImplementationForConstants() const override { return true; }
50	    bool useDefaultImplementationForNulls() const override { return false; }
51	
52	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t num_rows) const override
53	    {
54	        const auto * col_num = arguments[0].column.get();
55	        const auto * col_value = arguments[1].column.get();
56	
57	        auto offsets_col = ColumnArray::ColumnOffsets::create();
58	        ColumnArray::Offsets & offsets = offsets_col->getData();
59	        offsets.reserve(num_rows);
60	
61	        ColumnArray::Offset offset = 0;
62	        for (size_t i = 0; i < num_rows; ++i)
63	        {
64	            auto array_size = col_num->getInt(i);
65	
66	            if (unlikely(array_size < 0))
67	                throw Exception("Array size cannot be negative: while executing function " + getName(), ErrorCodes::TOO_LARGE_ARRAY_SIZE);
68	
69	            offset += array_size;
70	
71	            if (unlikely(offset > max_arrays_size_in_columns))
72	                throw Exception("Too large array size while executing function " + getName(), ErrorCodes::TOO_LARGE_ARRAY_SIZE);
73	
74	            offsets.push_back(offset);
75	        }
76	
77	        return ColumnArray::create(col_value->replicate(offsets)->convertToFullColumnIfConst(), std::move(offsets_col));
78	    }
79	};
80	
81	void registerFunctionArrayWithConstant(FunctionFactory & factory)
82	{
83	    factory.registerFunction<FunctionArrayWithConstant>();
84	}
